 namespace nRUNLTS {

+// Register-value component of the statistical corrector.
+// Each tracked architectural register remembers the value of its newest decoded
+// producer once that producer has executed; an older producer that executes late is
+// ignored. At prediction, the registers whose available values come from the youngest
+// producers are hashed with the branch PC into one table of signed counters, once with
+// the exact value and once with a coarse class of the value (magnitude, sign, low
+// bits). The two lookup groups have their own usefulness weights, and saturated
+// counters are trusted more.
+static constexpr int RvTracked = 33; // x0-x30, sp and the flags register
+static constexpr int RvPick = 6; // youngest available registers considered
+static constexpr int RvExact = 6; // registers looked up with their exact value
+static constexpr int RvCoarse = 6; // registers looked up with their value class
+static constexpr int RvSlots = RvExact + RvCoarse;
+static constexpr int RvLogTable = 13;
+static constexpr int RvCtrMax = 31;
+static constexpr int RvCtrMin = -32;
+static constexpr int RvBoost = 3; // contribution multiplier of a saturated counter
+static constexpr int RvLogWeight = 3;
+
+struct RvReg {
+    uint64_t value; // value of the newest decoded producer, once executed
+    uint32_t producer; // low 32 bits of the newest decoded producer seq_no
+    uint8_t valid : 1; // that producer has executed
+};
+
+struct RvCtr {
+    int8_t v : 6;
+};
+
+struct RvSlot {
+    uint16_t idx : 13; // counter index chosen at prediction
+    uint16_t on : 1;
+};
+
 static constexpr int LogMaxNewlyCounters = 16;

 static constexpr int NHIST = 23;
@@ -599,6 +633,7 @@ struct cbp_hist_t {
     tage_index_t ch_i;
     std::array<tage_tag_t, 2> ch_t;
     int perceptron_sum_at_prediction;
+    std::array<RvSlot, RvSlots> rv_slots {}; // register-value counter indices at prediction

     // Begin Conventional Histories
     uint64_t phist; // path history
@@ -844,6 +879,176 @@ public:
         current_hist.phist = 0;
     } // end init_histories

+    // ---- Register-value component state ----
+    std::array<RvReg, RvTracked> rv_regs {};
+    std::array<RvCtr, (1 << RvLogTable)> rv_table {};
+    std::array<RvCtr, (2 << RvLogWeight)> rv_weight {}; // per group and PC bucket
+
+    // tracked index of an architectural destination register, or -1
+    int rv_map(uint64_t dst_reg) const
+    {
+        if (dst_reg < 32)
+            return dst_reg;
+        if (dst_reg == 64)
+            return 32;
+        return -1;
+    }
+
+    int rv_hash(uint64_t PC, int salt, int r, uint64_t v) const
+    {
+        uint64_t h = v ^ (v >> 29) ^ (v >> 47);
+        h *= 0x9E3779B97F4A7C15ull;
+        h ^= (PC ^ (PC >> 5)) * 0xC2B2AE3D27D4EB4Full;
+        h += (r + 1) * 0x165667B19E3779F9ull + salt * 0x27D4EB2F165667C5ull;
+        h ^= h >> 31;
+        h *= 0xD6E8FEB86659FD93ull;
+        return h >> (64 - RvLogTable);
+    }
+
+    // magnitude class, sign and two low bits: generalizes across nearby values
+    uint64_t rv_coarse(uint64_t v) const
+    {
+        int mag = 0;
+        uint64_t a = v;
+        if (v >> 63)
+            a = 0 - v;
+        while (a != 0 && mag < 63) {
+            a >>= 1;
+            ++mag;
+        }
+        uint64_t f = mag;
+        f = (f << 1) | (v >> 63);
+        f = (f << 2) | (v & 3);
+        return f + 0x51ED;
+    }
+
+    // select the registers with the youngest executed producers and hash them with the PC
+    std::array<RvSlot, RvSlots> rv_capture(uint64_t seq_no, uint64_t PC) const
+    {
+        std::array<int, RvPick> best_reg {};
+        std::array<uint32_t, RvPick> best_age {};
+        std::fill(best_reg.begin(), best_reg.end(), -1);
+        std::fill(best_age.begin(), best_age.end(), 0xFFFFFFFFu);
+        const uint32_t now = seq_no;
+        for (int r = 0; r < RvTracked; ++r) {
+            if (rv_regs.at(r).valid == 0)
+                continue;
+            const uint32_t age = now - rv_regs.at(r).producer;
+            int pos = RvPick;
+            while (pos > 0 && age < best_age.at(pos - 1))
+                --pos;
+            if (pos >= RvPick)
+                continue;
+            for (int q = RvPick - 1; q > pos; --q) {
+                best_age.at(q) = best_age.at(q - 1);
+                best_reg.at(q) = best_reg.at(q - 1);
+            }
+            best_age.at(pos) = age;
+            best_reg.at(pos) = r;
+        }
+        std::array<RvSlot, RvSlots> slots {};
+        for (int j = 0; j < RvExact; ++j) {
+            const int r = best_reg.at(j);
+            if (r < 0)
+                continue;
+            slots.at(j).idx = rv_hash(PC, 1, r, rv_regs.at(r).value);
+            slots.at(j).on = 1;
+        }
+        for (int j = 0; j < RvCoarse; ++j) {
+            const int r = best_reg.at(j);
+            if (r < 0)
+                continue;
+            slots.at(RvExact + j).idx = rv_hash(PC, 98, r, rv_coarse(rv_regs.at(r).value));
+            slots.at(RvExact + j).on = 1;
+        }
+        return slots;
+    }
+
+    // sum of the counters of group g (0: exact values, 1: value classes)
+    int rv_group_sum(int g, const std::array<RvSlot, RvSlots>& slots) const
+    {
+        const int first = g == 0 ? 0 : RvExact;
+        const int last = g == 0 ? RvExact : RvSlots;
+        int sum = 0;
+        for (int j = first; j < last; ++j) {
+            if (slots.at(j).on == 0)
+                continue;
+            const int cv = rv_table.at(slots.at(j).idx).v;
+            int c = 2 * cv + 1;
+            if (cv >= RvCtrMax || cv <= RvCtrMin)
+                c *= RvBoost;
+            sum += c;
+        }
+        return sum;
+    }
+
+    int rv_weight_index(int g, uint64_t PC) const { return (g << RvLogWeight) + ((PC ^ (PC >> 2)) & ((1 << RvLogWeight) - 1)); }
+
+    int rv_doubled(int g, uint64_t PC) const { return rv_weight.at(rv_weight_index(g, PC)).v >= 0; }
+
+    int rv_weighted_sum(uint64_t PC, const std::array<RvSlot, RvSlots>& slots) const
+    {
+        return (1 + rv_doubled(0, PC)) * rv_group_sum(0, slots) + (1 + rv_doubled(1, PC)) * rv_group_sum(1, slots);
+    }
+
+    int rv_extra_weight(uint64_t PC) const { return 2 * rv_doubled(0, PC) + 2 * rv_doubled(1, PC); }
+
+    void rv_train(uint64_t PC, bool taken, int lsum, const std::array<RvSlot, RvSlots>& slots)
+    {
+        // weight update of each group, as for the retained component groups
+        for (int g = 0; g < 2; ++g) {
+            const int sum = rv_group_sum(g, slots);
+            const int rest = lsum - (1 + rv_doubled(g, PC)) * sum;
+            const bool pred_single = rest + sum >= 0;
+            const bool pred_double = rest + 2 * sum >= 0;
+            if (pred_single != pred_double) {
+                const int wi = rv_weight_index(g, PC);
+                const int w = rv_weight.at(wi).v;
+                if ((sum >= 0) == taken) {
+                    if (w < RvCtrMax)
+                        rv_weight.at(wi).v = w + 1;
+                } else {
+                    if (w > RvCtrMin)
+                        rv_weight.at(wi).v = w - 1;
+                }
+            }
+        }
+        for (int j = 0; j < RvSlots; ++j) {
+            if (slots.at(j).on == 0)
+                continue;
+            const int i = slots.at(j).idx;
+            const int c = rv_table.at(i).v;
+            if (taken) {
+                if (c < RvCtrMax)
+                    rv_table.at(i).v = c + 1;
+            } else {
+                if (c > RvCtrMin)
+                    rv_table.at(i).v = c - 1;
+            }
+        }
+    }
+
+    void rv_decode(uint64_t seq_no, uint64_t dst_reg)
+    {
+        const int r = rv_map(dst_reg);
+        if (r < 0)
+            return;
+        rv_regs.at(r).producer = seq_no;
+        rv_regs.at(r).valid = 0;
+    }
+
+    void rv_execute(uint64_t seq_no, uint64_t dst_reg, uint64_t value)
+    {
+        const int r = rv_map(dst_reg);
+        if (r < 0)
+            return;
+        const uint32_t id = seq_no;
+        if (rv_regs.at(r).producer != id)
+            return; // superseded by a newer decoded producer
+        rv_regs.at(r).value = value;
+        rv_regs.at(r).valid = 1;
+    }
+
     // the index functions for the tagged tables uses path history as in the OGEHL predictor
     // F serves to mix path history: not very important impact
     int F(uint64_t A, int size, int bank) const
@@ -1021,8 +1226,8 @@ public:
 #endif
         pv.pred_inter = pv.tage_pred; // We don't use the Loop Predictor, thus, pred_inter is the same as tage_pred.

